/* Stapel – Karteninhalte
   Format: { c: Kategorie-Key, t: Titel, b: Text, x: optionale Vertiefung }
   Kategorien: fert = Fertigung & CAD, teil = Bauteile,
               elek = Elektronik, auto = Auto & Oldtimer, fin = Finanzen
   Neue Karten einfach unten anhängen. Reihenfolge egal, wird gemischt. */

window.CARDS = [

/* ---------- FERTIGUNG & CAD ---------- */
{c:"fert",t:"Die 45-Grad-Regel",b:"Überhänge bis 45° drucken sauber, weil jede Schicht noch mindestens die Hälfte ihrer Breite auf der vorherigen aufliegt. Ab 45° kippt das Verhältnis: die Bahn hängt mehr in der Luft als auf Material und rollt sich ein.",x:"Deshalb lohnt es sich, Bauteile schon im CAD mit 45°-Fasen statt 90°-Absätzen zu konstruieren – dann brauchst du gar keinen Support."},
{c:"fert",t:"Warum der Elefantenfuß entsteht",b:"Die erste Schicht wird bewusst gequetscht, damit sie haftet. Gleichzeitig ist das Bett heiß, das Material bleibt lange weich und das Gewicht der Schichten darüber drückt es seitlich raus. Ergebnis: die untersten 0,3 mm sind breiter als der Rest.",x:"Fixes: Bett 5 °C kälter, erste Schicht weniger quetschen, oder im Slicer eine negative Fase auf der ersten Schicht (Elephant Foot Compensation, meist 0,1–0,2 mm)."},
{c:"fert",t:"Gedruckte Teile sind anisotrop",b:"In XY-Richtung trägt der extrudierte Strang selbst die Last – du nutzt die volle Materialfestigkeit. In Z-Richtung hält nur die Verschweißung zwischen den Schichten, und die erreicht je nach Material 30–70 % davon.",x:"Praxisregel: Die Hauptlast soll nie senkrecht durch die Schichtebenen laufen. Bauteil notfalls schräg oder liegend orientieren, auch wenn dann Support nötig wird."},
{c:"fert",t:"Warping ist Schwindung",b:"Jedes Thermoplast schrumpft beim Abkühlen. ABS etwa 0,8 %, PLA nur 0,3 %. Die untere Schicht ist am Bett fixiert und schon kalt, die oberen kühlen später ab und ziehen sich zusammen – die Spannung reißt die Ecken hoch.",x:"Deshalb hilft ein geschlossener Bauraum mehr als jede Haftlösung: Wenn alle Schichten gleichmäßig warm bleiben, schrumpfen sie gemeinsam statt gegeneinander."},
{c:"fert",t:"Perimeter schlagen Infill",b:"Ein Bauteil auf Biegung ist wie ein Träger: die äußersten Fasern nehmen die Spannung auf, die Mitte trägt fast nichts. Von 2 auf 4 Wandlinien zu gehen bringt mehr Steifigkeit als Infill von 20 % auf 50 % – und kostet weniger Material und Zeit.",x:"Faustregel für Funktionsteile: 4 Perimeter, 5 Boden-/Deckschichten, 15–20 % Infill. Erst wenn Druckkräfte senkrecht wirken, wird Infill wirklich wichtig."},
{c:"fert",t:"Warum Gyroid-Infill beliebt ist",b:"Gyroid ist eine dreifach periodische Minimalfläche. Sie hat in allen drei Raumrichtungen ähnliche Steifigkeit, die Bahnen kreuzen sich nirgends, und der Kopf muss nie über schon gedrucktes Material fahren.",x:"Nachteil: viele Richtungswechsel, deshalb langsamer als Gitter oder Linien. Für Teile, die aus unbekannter Richtung belastet werden, trotzdem meist die beste Wahl."},
{c:"fert",t:"Die Glasübergangstemperatur",b:"Tg ist nicht der Schmelzpunkt, sondern der Punkt, an dem ein amorpher Kunststoff vom harten Zustand in den gummiartigen wechselt. PLA liegt bei etwa 60 °C, PETG bei 80 °C, ABS bei 105 °C, PC bei 145 °C.",x:"Deshalb verformt sich ein PLA-Halter im Auto im Sommer. Im Innenraum hinter Glas werden 70 °C erreicht – PETG oder ASA sind dort das Minimum."},
{c:"fert",t:"PETG haftet zu gut",b:"PETG geht mit PEI eine chemische Bindung ein und reißt beim Ablösen Stücke aus der Druckplatte. Das ist kein Haftungsproblem, sondern das Gegenteil.",x:"Gegenmittel: dünne Schicht Klebestift als Trennmittel, oder eine glatte PEI-Platte statt der strukturierten, oder Z-Offset minimal höher, damit die erste Schicht nicht in die Textur gepresst wird."},
{c:"fert",t:"Carbonfaser macht steif, nicht fest",b:"Die Kurzfasern in CF-Filamenten sind meist nur 0,1–0,3 mm lang. Sie erhöhen den E-Modul deutlich und reduzieren Verzug, weil sie die Schwindung bremsen. Die Bruchfestigkeit steigt kaum – oft sinkt sie sogar, weil die Fasern Kerben bilden.",x:"CF wählst du also für Formstabilität und Maßhaltigkeit, nicht wenn ein Teil möglichst viel Kraft aushalten soll. Dafür ist ungefülltes PA oder PETG oft besser."},
{c:"fert",t:"Warum CF Düsen frisst",b:"Messing hat etwa 100 HV Härte, Kohlefaser liegt weit darüber. Jeder Zentimeter Filament wirkt wie feines Schleifmittel auf die Düsenbohrung. Nach wenigen hundert Gramm ist aus 0,4 mm eine unrunde 0,5 mm geworden.",x:"Gehärteter Stahl hält, leitet aber schlechter Wärme – Temperatur etwa 10 °C höher wählen. Rubin- oder Wolframcarbid-Düsen kombinieren beides, kosten aber deutlich mehr."},
{c:"fert",t:"Hygroskopische Filamente",b:"Nylon nimmt bis zu 10 % seines Gewichts an Wasser auf, PETG und TPU deutlich weniger, PLA am wenigsten. In der Düse verdampft das Wasser schlagartig und sprengt den Strang auf – daher Knistern, Blasen und matte, poröse Oberflächen.",x:"Trocknen heißt nicht erhitzen: 6–12 h bei 70 °C für PA, 55 °C für PETG. Danach in Box mit Trockenmittel, sonst ist der Effekt nach zwei Tagen in der Halle wieder da."},
{c:"fert",t:"Die Z-Naht ist kein Fehler",b:"Irgendwo muss jede geschlossene Kontur anfangen und aufhören. An dieser Stelle entsteht ein kleiner Druckabfall und ein Materialüberschuss. Der Slicer kann sie zufällig verteilen, an schärfsten Ecken verstecken oder auf eine feste Achse legen.",x:"Für Sichtteile: Naht bewusst auf eine Kante oder Rückseite legen. Zufällige Verteilung sieht auf runden Teilen oft schlechter aus als eine saubere gerade Linie."},
{c:"fert",t:"Warum Bridging funktioniert",b:"Zwischen zwei Auflagepunkten wird die Bahn nicht abgelegt, sondern gespannt. Der Strang kühlt in der Luft und zieht sich zusammen, dadurch strafft er sich selbst. Entscheidend ist maximale Kühlung und eine reduzierte Geschwindigkeit, damit der Faden nicht abreißt.",x:"Überhänge über 10 mm brauchen Support – Brücken über 50 mm gelingen oft trotzdem, weil der Zug entlang der Bahn wirkt und nicht quer."},
{c:"fert",t:"Löcher werden immer zu klein",b:"Der Drucker fährt die Kontur eines Kreises als Polygon ab, und der Extrudatstrang hat eine Breite. An der Innenseite einer Krümmung wird das Material gestaucht – es wandert nach innen. Ein 5-mm-Loch misst nachher oft 4,7 mm.",x:"Lösungen: Hole Compensation im Slicer, Loch im CAD 0,2–0,3 mm größer zeichnen, oder wichtige Passungen grundsätzlich nachbohren bzw. reiben."},
{c:"fert",t:"Gewinde in Druckteilen",b:"Ein direkt gedrucktes M3-Gewinde hat wenige tragende Gänge und schert beim zweiten Anziehen aus. Eingepresste Messing-Gewindeeinsätze verteilen die Last dagegen über eine Rändelung auf die Wand und halten Hunderte Zyklen.",x:"Loch etwa 0,1 mm kleiner als der Einsatz-Außendurchmesser, Lötkolben auf 220 °C, langsam senkrecht einsenken. Ab M5 sind gedruckte Gewinde in Steigung und Tragfläche wieder brauchbar."},
{c:"fert",t:"Mikroschritte kosten Drehmoment",b:"Ein Schrittmotor mit 1/16-Mikroschritten läuft leiser und feiner, aber das Haltemoment pro Mikroschritt sinkt mit dem Sinus des Winkels. Bei sehr feiner Auflösung ist die Kraft, die eine Position hält, minimal – der Motor verliert Schritte, bevor du es merkst.",x:"Deshalb bringen 1/256 Mikroschritte keine echte Genauigkeit. Sie glätten nur den Lauf; die mechanische Auflösung kommt aus Spindelsteigung und Riementeilung."},
{c:"fert",t:"Input Shaping",b:"Jeder Druckerrahmen hat eine Eigenfrequenz, meist 30–70 Hz. Beschleunigt der Kopf, regt er sie an und der Aufbau schwingt nach – das sind die Echos hinter jeder Ecke (Ringing). Input Shaping misst diese Frequenz und teilt jede Bewegung so auf, dass die zweite Anregung die erste auslöscht.",x:"Deshalb kann eine Klipper-Maschine mit demselben Rahmen doppelt so schnell drucken. Die Mechanik wird nicht besser, nur die Ansteuerung schlauer."},
{c:"fert",t:"Innenecken haben immer einen Radius",b:"Ein Fräser ist rund. Eine scharfe Innenecke lässt sich schlicht nicht fräsen – es bleibt immer mindestens der Werkzeugradius stehen. Wer im CAD eine scharfe Innenecke zeichnet, zwingt den Fertiger zu Erodieren oder Räumen.",x:"Konstruktionsregel: Innenradius mindestens Werkzeugradius plus 10–20 %, damit der Fräser nicht in voller Breite eintaucht. Bei einem 6-mm-Fräser also R3,5 statt R3."},
{c:"fert",t:"Gleichlauf oder Gegenlauf",b:"Im Gleichlauf dreht sich der Fräser in Vorschubrichtung, der Span beginnt dick und läuft dünn aus. Das ergibt bessere Oberflächen, weniger Wärme im Werkzeug und weniger Verschleiß. Gegenlauf reibt am Anfang des Spans und härtet die Oberfläche.",x:"Gleichlauf zieht die Maschine allerdings in den Schnitt. Auf alten Maschinen mit Spiel in der Trapezspindel deshalb lieber Gegenlauf – auf jeder Kugelgewindetrieb-Maschine immer Gleichlauf."},
{c:"fert",t:"Zu langsam ist schlimmer als zu schnell",b:"Entscheidend ist der Vorschub pro Zahn. Ist er zu klein, schneidet die Schneide nicht mehr, sondern quetscht und reibt – die Wärme geht ins Werkzeug statt in den Span, und die Schneidkante stumpft ab.",x:"Ein Span führt Wärme ab. Deshalb gilt in der Zerspanung: lieber höherer Vorschub bei geringerer Zustellung als umgekehrt. Blau anlaufende Späne sind ein gutes Zeichen, glühende nicht."},
{c:"fert",t:"Warum Alu schmiert",b:"Aluminium ist weich und klebt an der Schneide fest (Aufbauschneide). Der angeschweißte Span verändert die Geometrie, reißt ab und nimmt Material aus der Schneide mit. Das Werkzeug stirbt nicht durch Verschleiß, sondern durch Ausbrüche.",x:"Hilft: scharfe, polierte Schneiden, wenige Schneiden (2–3 statt 4), hohe Schnittgeschwindigkeit, und Kühlschmierung oder wenigstens Druckluft zum Spänefreiblasen."},
{c:"fert",t:"CO2- oder Diodenlaser",b:"Ein CO2-Laser arbeitet bei 10,6 µm Wellenlänge. Diese Strahlung wird von fast allen Kunststoffen absorbiert, deshalb schneidet er Acryl glatt und flammpoliert. Ein Diodenlaser bei 445 nm ist blau – transparentes Acryl lässt ihn einfach durch.",x:"Faustregel: Dioden für Holz, Leder, dunkle Materialien und Gravuren. CO2 für Acryl, klare Kunststoffe und saubere Schnittkanten. Metall schneidet keiner von beiden."},
{c:"fert",t:"Kerf – die Schnittfuge",b:"Der Laserstrahl hat eine Breite, meist 0,1–0,3 mm. Er verdampft Material links und rechts der Kontur. Wer auf Kontur schneidet, bekommt Außenteile zu klein und Löcher zu groß – jeweils um den halben Kerf.",x:"Für Steckverbindungen: Kerf einmal an einem Teststreifen messen und im CAM als Offset hinterlegen. Dann passen Nut und Feder auf Anhieb."},
{c:"fert",t:"Der Saugnapf-Effekt beim Harzdruck",b:"Bei jeder Schicht muss sich das Teil vom FEP-Film lösen. Große flache Querschnitte erzeugen dabei einen Unterdruck, der stärker zieht als die Haftung auf der Plattform. Deshalb reißen flach liegende Platten ab.",x:"Teile 20–30° schräg stellen. Dann löst sich die Schicht progressiv von einer Kante her statt auf einen Schlag – das reduziert die Kraft um ein Vielfaches."},
{c:"fert",t:"Warum SLA-Teile spröde werden",b:"Nachhärten vernetzt die restlichen Monomere. Zu lange oder zu heiß, und das Material wird durchgehend hart und glasartig – besonders bei flexiblen Harzen verliert man genau die Eigenschaft, für die man sie gekauft hat.",x:"Auch IPA ist ein Faktor: zu langes Bad quillt das Teil auf und laugt Weichmacher aus. Kurz waschen, gründlich abblasen, dann dosiert härten."},
{c:"fert",t:"Vollständig bestimmte Skizzen",b:"Eine Skizze ohne ausreichende Bemaßung hat Freiheitsgrade. Solange die bestehen, kann jede spätere Änderung die Geometrie unvorhersehbar verschieben – das ist die Hauptursache für zusammenbrechende Feature-Bäume.",x:"In Fusion färbt sich die Skizze schwarz, sobald sie vollständig bestimmt ist. Eine Minute Mehrarbeit dort spart eine Stunde Reparatur bei der ersten Maßänderung."},
{c:"fert",t:"Kraftfluss denken",b:"Kraft sucht sich immer den steifsten Weg durch ein Bauteil. Wo sich dieser Weg stark verengt oder scharf umlenkt, entstehen Spannungsspitzen. Gute Konstruktion führt Kraft auf möglichst kurzem, gleichmäßigem Weg vom Angriffspunkt zur Abstützung.",x:"Deshalb sind Rippen entlang der Kraftrichtung wirksam und quer dazu nutzlos. Und deshalb bricht ein Teil fast immer an der Stelle, wo der Querschnitt plötzlich springt."},
{c:"fert",t:"Kerbwirkung",b:"Eine scharfe Innenecke kann die örtliche Spannung um den Faktor 3 und mehr erhöhen. Das Material daneben ist völlig unbelastet, aber im Kerbgrund reißt es. Ein Radius verteilt die Spannung über eine Länge statt sie auf einen Punkt zu konzentrieren.",x:"Ein Radius von 10 % der Wandstärke nimmt schon den Großteil der Spitze weg. Größer bringt danach nur noch wenig – aber gar kein Radius ist immer ein Fehler."},
{c:"fert",t:"Prototyp ist nicht Serie",b:"Ein gedrucktes Teil hat andere Festigkeit, andere Oberfläche und andere Toleranzen als dasselbe Teil aus dem Spritzguss. Spritzguss schwindet je nach Material 0,4–2 % und braucht Entformschrägen, Wandstärken müssen gleichmäßig sein.",x:"Wer ein Druckteil 1:1 in ein Werkzeug gibt, bekommt Einfallstellen an dicken Stellen und Verzug. Serienreife heißt: neu konstruieren, nicht nur skalieren."},
{c:"fert",t:"Toleranzen kosten Geld",b:"Jede Stelle im Toleranzfeld hinter dem Komma vervielfacht den Aufwand. ±0,2 mm ist gedruckt oder gefräst fast geschenkt, ±0,05 mm braucht sorgfältige Aufspannung und Messung, ±0,01 mm heißt Schleifen und klimatisierter Raum.",x:"Deshalb auf Zeichnungen nur dort eng tolerieren, wo eine Funktion es verlangt – Passungen, Lagersitze, Dichtflächen. Der Rest bekommt Allgemeintoleranz."},

/* ---------- BAUTEILE ---------- */
{c:"teil",t:"Der Farbcode ist ein Zahlensystem",b:"Braun 1, Rot 2, Orange 3, Gelb 4, Grün 5, Blau 6, Violett 7, Grau 8, Weiß 9, Schwarz 0. Die ersten Ringe sind Ziffern, der vorletzte ist der Multiplikator, der abgesetzte hinten die Toleranz – Gold bedeutet 5 %, Braun 1 %.",x:"Die Reihenfolge folgt grob dem Spektrum von Rot nach Violett. Wer das einmal als Reihe sieht statt als Liste, vergisst es nicht mehr."},
{c:"teil",t:"Warum 4,7 und nicht 5",b:"Widerstandswerte folgen der E-Reihe, einer geometrischen Folge. E12 teilt eine Dekade in 12 Schritte, jeder etwa Faktor 1,21 – damit sich die Toleranzfelder von ±10 % gerade lückenlos aneinanderreihen.",x:"Deshalb existiert 4,7 kΩ, aber kein 5 kΩ. Die Reihe ist nach Toleranz gebaut, nicht nach runden Zahlen: E24 hat ±5 %, E96 hat ±1 %."},
{c:"teil",t:"Keramikkondensatoren verlieren Kapazität",b:"X7R- und Y5V-Typen ändern ihre Kapazität mit der angelegten Spannung. Ein 10-µF-Kondensator für 16 V kann bei tatsächlichen 12 V nur noch 3 µF haben. C0G/NP0 ist stabil, gibt es aber nur in kleinen Werten.",x:"Praxisregel: Nennspannung mindestens doppelt so hoch wählen wie die Betriebsspannung. Nicht wegen Durchschlag, sondern damit die Kapazität erhalten bleibt."},
{c:"teil",t:"Elkos altern durch Wärme",b:"Im Elektrolytkondensator verdunstet der Elektrolyt durch die Dichtung. Die Lebensdauer halbiert sich pro 10 °C mehr – oder verdoppelt sich pro 10 °C weniger. Ein 2000-h-Typ bei 105 °C hält bei 65 °C rechnerisch 32.000 Stunden.",x:"Deshalb sterben Netzteile zuerst an den Elkos neben dem Kühlkörper. Beim Reparieren: nicht den defekten tauschen, sondern alle in der Wärmezone."},
{c:"teil",t:"Warum Tantalkondensatoren brennen",b:"Tantal hat eine extrem dünne Oxidschicht als Dielektrikum. Bricht sie an einer Fehlstelle durch, wird der Kurzschlussstrom in einen winzigen Punkt geleitet – das Tantal oxidiert exotherm und brennt weiter, auch ohne Luft.",x:"Deshalb Tantal mit mindestens doppelter, besser dreifacher Spannungsreserve einsetzen. Oder gleich moderne Polymer- bzw. Keramiktypen verwenden."},
{c:"teil",t:"0,7 Volt kosten Wärme",b:"Eine Silizium-Diode fällt etwa 0,7 V ab, unabhängig vom Strom. Bei 3 A sind das 2,1 W Verlustleistung als reine Wärme. Eine Schottky-Diode kommt mit 0,3 V aus – gleiche Schaltung, weniger als die Hälfte der Verluste.",x:"Schottky-Nachteil: höherer Sperrstrom, besonders bei Wärme, und geringere Sperrspannung. Für Netzgleichrichtung deshalb weiterhin Silizium."},
{c:"teil",t:"Die Zenerdiode arbeitet rückwärts",b:"In Sperrrichtung bricht sie bei einer definierten Spannung sauber durch und hält diese Spannung dann fest, solange der Strom begrenzt wird. Ohne Vorwiderstand stirbt sie sofort – der Widerstand ist Teil der Schaltung, kein Zubehör.",x:"Für eine stabile Referenz reicht sie nur bedingt: die Spannung driftet mit Temperatur und Laststrom. Präzise Referenzen sind eigene ICs."},
{c:"teil",t:"Warum eine LED einen Vorwiderstand braucht",b:"Eine LED hat keine lineare Kennlinie. Oberhalb der Flussspannung steigt der Strom fast senkrecht an – 0,1 V mehr können den Strom verdoppeln. Ohne Strombegrenzung heizt sie sich auf, die Flussspannung sinkt dabei, der Strom steigt weiter. Das endet immer gleich.",x:"Formel: R = (Versorgungsspannung − Flussspannung) / gewünschter Strom. Bei 5 V, roter LED mit 2 V und 15 mA also 200 Ω – nächster Normwert 220 Ω."},
{c:"teil",t:"Bipolartransistor heißt Stromverstärker",b:"Ein NPN leitet vom Kollektor zum Emitter, wenn Basisstrom fließt. Das Verhältnis ist die Stromverstärkung hFE, typisch 100–400. Für 1 A Kollektorstrom brauchst du also mindestens rund 10 mA Basisstrom – die muss dein Mikrocontroller-Pin liefern können.",x:"Im Schaltbetrieb rechnet man bewusst mit einem Faktor 10 statt mit hFE, damit der Transistor sicher in die Sättigung geht und wenig Wärme macht."},
{c:"teil",t:"Der MOSFET braucht Spannung, keinen Strom",b:"Das Gate ist durch eine Isolierschicht vom Kanal getrennt – statisch fließt kein Strom. Nur beim Umschalten muss die Gate-Kapazität umgeladen werden. Deshalb schalten MOSFETs mit fast null Steuerleistung, brauchen beim schnellen Schalten aber kräftige Treiber.",x:"Der wichtigste Wert im Datenblatt ist Rds(on): der Widerstand im durchgeschalteten Zustand. Bei 10 mΩ und 20 A sind das 4 W Verlustleistung."},
{c:"teil",t:"Die Logic-Level-Falle",b:"Ein Standard-MOSFET braucht 10 V am Gate, um voll durchzuschalten. Ein 3,3-V-Mikrocontroller bringt ihn nur in den Teillastbereich – er leitet scheinbar, hat aber hohen Widerstand und wird heiß. Der Fehler zeigt sich erst unter Last.",x:"Achte im Datenblatt darauf, bei welcher Gate-Spannung Rds(on) angegeben ist. Steht dort 10 V, ist der Typ an einem 3,3-V-Pin die falsche Wahl."},
{c:"teil",t:"Der Optokoppler trennt galvanisch",b:"Innen sitzen eine LED und ein Fototransistor ohne elektrische Verbindung. Signal geht als Licht über den Spalt. Damit lassen sich Stromkreise mit verschiedenen Massen oder mit 230 V sicher koppeln, und Masseschleifen verschwinden.",x:"Der Kennwert heißt CTR – wie viel Kollektorstrom pro LED-Strom herauskommt. Er sinkt über die Lebensdauer, also nicht auf Kante dimensionieren."},
{c:"teil",t:"Die Freilaufdiode rettet den Transistor",b:"Eine Relaisspule ist eine Induktivität. Wird der Strom abrupt abgeschaltet, erzeugt das Magnetfeld eine Gegenspannung, die mehrere hundert Volt erreichen kann. Die Diode antiparallel zur Spule gibt diesem Strom einen Weg im Kreis.",x:"Ohne sie stirbt der Schalttransistor – manchmal sofort, oft nach ein paar tausend Schaltvorgängen. Bei Relais immer einbauen, auch wenn es kurzzeitig ohne läuft."},
{c:"teil",t:"Strom in einer Spule kann nicht springen",b:"Der Kondensator wehrt sich gegen Spannungsänderung, die Spule gegen Stromänderung. Genau daraus entsteht jeder Schaltregler: Man schaltet Spannung ein und aus, die Spule glättet daraus einen kontinuierlichen Strom.",x:"Die Kernsättigung ist die Grenze. Ist der Strom zu hoch, verliert der Kern seine Permeabilität, die Induktivität bricht zusammen und der Strom schießt hoch."},
{c:"teil",t:"Ferritperle statt Drossel",b:"Eine Ferritperle ist keine gute Induktivität, sondern ein frequenzabhängiger Widerstand. Bei Gleichstrom nahezu unsichtbar, bei 100 MHz mehrere hundert Ohm – sie wandelt Störenergie in Wärme statt sie zu reflektieren.",x:"Deshalb wird sie in Versorgungsleitungen von HF-Modulen eingesetzt. Ihr Datenblattwert gilt bei 100 MHz, nicht bei der Betriebsfrequenz."},
{c:"teil",t:"Quarze brauchen die richtige Last",b:"Ein Quarz schwingt nur dann exakt auf seiner Nennfrequenz, wenn er die im Datenblatt angegebene Lastkapazität sieht, typisch 12–20 pF. Die beiden Kondensatoren gegen Masse sind kein Beiwerk, sondern stellen genau diese Last ein.",x:"Falsche Werte bedeuten Frequenzabweichung – beim UART zeigt sich das als kaputte Zeichen, bei Funkmodulen als verschobener Kanal."},
{c:"teil",t:"Der 7805 verheizt die Differenz",b:"Ein Linearregler ist im Kern ein geregelter Widerstand. Aus 12 V werden 5 V, indem 7 V in Wärme umgesetzt werden. Bei 500 mA sind das 3,5 W – der Wirkungsgrad liegt bei 42 %.",x:"Im Auto mit 14 V Bordnetz wird das schnell zum Problem. Ein Step-Down-Modul erreicht dort über 90 % und braucht keinen Kühlkörper."},
{c:"teil",t:"LDO oder Schaltregler",b:"Ein LDO ist leise, klein und braucht keine Spule – ideal für analoge Sensorik und HF, aber nur bei kleiner Spannungsdifferenz. Ein Step-Down ist effizient, erzeugt aber Schaltrauschen im Bereich einiger hundert kHz.",x:"Übliche Kombination: Step-Down auf 3,6 V für die Grobversorgung, danach ein LDO auf 3,3 V für den empfindlichen Teil der Schaltung."},
{c:"teil",t:"Pull-up-Widerstände",b:"Ein Eingang ohne definierte Beschaltung ist kein Nullpegel, sondern eine kleine Antenne. Er nimmt Störungen auf und kippt zufällig. Ein Pull-up zieht ihn auf High, bis ein Taster ihn aktiv auf Masse zieht.",x:"Typisch 10 kΩ: klein genug gegen Störeinflüsse, groß genug, um im geschlossenen Zustand kaum Strom zu verbrauchen. Bei I2C sind 4,7 kΩ üblich, weil dort schnell geschaltet wird."},
{c:"teil",t:"Der 100-nF-Kondensator am IC",b:"Wenn ein Digitalbaustein schaltet, zieht er für Nanosekunden einen Stromimpuls. Die Zuleitung vom Netzteil ist dafür zu träge – sie hat Induktivität. Der Abblockkondensator sitzt direkt am Pin und liefert diese Spitze lokal.",x:"Entscheidend ist der Abstand, nicht der Wert. 100 nF zwei Zentimeter entfernt wirken schlechter als 10 nF direkt am Pin."},
{c:"teil",t:"Sicherungen: flink oder träge",b:"Eine träge Sicherung toleriert kurze Einschaltströme, wie sie Netzteile und Motoren erzeugen, und löst erst bei anhaltender Überlast aus. Eine flinke reagiert in Millisekunden und schützt Halbleiter, die eine Überlast keine Sekunde überstehen.",x:"Polyfuses sind rückstellbar: sie werden im Fehlerfall hochohmig und kühlen danach wieder ab. Sie sind aber langsam und ihr Auslösewert driftet über die Jahre."},
{c:"teil",t:"TVS-Diode gegen Spannungsspitzen",b:"Eine TVS-Diode leitet erst oberhalb ihrer Durchbruchspannung und kann dann für Mikrosekunden hunderte Ampere aufnehmen. Sie ist dafür gebaut, Energie kurzzeitig zu vernichten und danach weiterzuarbeiten.",x:"Im Kfz-Bereich Pflicht: Load Dump beim Abklemmen der Batterie bei laufendem Motor erzeugt Spitzen über 60 V. Ohne Schutz stirbt jedes angeschlossene Steuergerät."},
{c:"teil",t:"Strommessung über Shunt",b:"Ein sehr kleiner, präziser Widerstand im Strompfad erzeugt einen Spannungsabfall proportional zum Strom. Bei 10 mΩ und 5 A fallen 50 mV ab – das misst ein Verstärker und rechnet zurück.",x:"Der Shunt muss vierpolig angeschlossen werden: Strom über die dicken Anschlüsse, Messung über getrennte Abgriffe. Sonst misst du den Übergangswiderstand der Lötstelle mit."},
{c:"teil",t:"Linear oder logarithmisch",b:"Ein lineares Poti teilt den Widerstand gleichmäßig über den Drehwinkel. Ein logarithmisches folgt der Empfindlichkeit des Gehörs – deshalb sitzt es in Lautstärkereglern. Mit einem linearen Poti passiert dort die halbe Lautstärkeänderung auf den letzten 20 % des Wegs.",x:"Kennzeichnung: A oder log für logarithmisch, B oder lin für linear – bei japanischer und europäischer Beschriftung leider teilweise umgekehrt."},
{c:"teil",t:"NTC und PTC",b:"Ein NTC verringert seinen Widerstand mit steigender Temperatur – er ist der klassische Temperatursensor im 3D-Drucker und im Kühlwasser. Ein PTC erhöht ihn und wird deshalb als selbstbegrenzende Heizung oder rückstellende Sicherung eingesetzt.",x:"NTCs sind stark nichtlinear. Die Umrechnung läuft über die Steinhart-Hart-Gleichung oder eine Tabelle – deshalb muss im Slicer bzw. in der Firmware der richtige Thermistor-Typ stehen."},
{c:"teil",t:"Hallsensor statt Schalter",b:"Ein Hallsensor misst ein Magnetfeld ohne Kontakt und ohne Verschleiß. Schaltende Typen liefern High/Low ab einer Feldstärke, lineare eine proportionale Spannung – damit lassen sich auch Ströme berührungslos messen.",x:"Achtung auf unipolare und bipolare Typen: manche schalten nur bei Nordpol, andere brauchen zum Zurückschalten das umgekehrte Feld."},
{c:"teil",t:"HC und HCT sind nicht dasselbe",b:"74HC-Logik erkennt High ab etwa 70 % der Versorgungsspannung, bei 5 V also ab 3,5 V. Ein 3,3-V-Signal wird damit nicht sicher erkannt. 74HCT hat TTL-Pegel und schaltet schon ab 2,0 V – damit funktioniert die Kopplung.",x:"Das ist die häufigste Ursache für Schaltungen, die sporadisch laufen und bei Wärme oder langen Leitungen aussteigen."},
{c:"teil",t:"Bauform ist Belastbarkeit",b:"Ein 0805-Widerstand verträgt typisch 0,125 W, 0603 nur 0,1 W, 1206 immerhin 0,25 W. Die Fläche bestimmt, wie viel Wärme an die Leiterplatte abgegeben wird – der Widerstandswert selbst spielt dafür keine Rolle.",x:"Nachrechnen mit P = I²·R. Ein 1-Ω-Shunt in 0805 bei 0,5 A liegt mit 0,25 W schon doppelt über der Spezifikation."},
{c:"teil",t:"Absolute Maximum Ratings sind keine Betriebswerte",b:"Diese Tabelle im Datenblatt sagt nur, ab wann das Bauteil zerstört wird. Zwischen ihr und den Recommended Operating Conditions liegt der Bereich, in dem nichts kaputtgeht, aber auch keine Funktion garantiert ist.",x:"Wer in dieser Grauzone konstruiert, baut Geräte, die auf dem Tisch laufen und beim Kunden im Sommer ausfallen."},
{c:"teil",t:"Der Kondensator als Energiespeicher",b:"Die gespeicherte Energie ist ½·C·U². Die Spannung geht quadratisch ein – deshalb bringt ein Kondensator mit doppelter Spannung bei gleicher Kapazität die vierfache Energie.",x:"Deshalb sind Supercaps mit nur 2,7 V pro Zelle trotz riesiger Kapazität energetisch weit von einer Batterie entfernt. Ihre Stärke ist die Leistung, nicht der Inhalt."},

/* ---------- ELEKTRONIK & SCHALTUNGEN ---------- */
{c:"elek",t:"Ohm ist ein Denkwerkzeug",b:"U = R·I beschreibt nicht nur Widerstände, sondern jede Stelle, an der Spannung abfällt. Kontaktwiderstand, Kabelquerschnitt, eine korrodierte Masseverbindung – alles wird damit rechenbar. Wer einen Spannungsabfall misst, kennt sofort den unbekannten Widerstand.",x:"Fehlersuche-Trick: nicht Spannung gegen Masse messen, sondern über das verdächtige Bauteil hinweg. Ein Kabel, das 2 V abfällt, ist das Problem."},
{c:"elek",t:"Der Spannungsteiler hat eine Grenze",b:"Zwei Widerstände teilen eine Spannung im Verhältnis ihrer Werte. Sobald eine Last daran hängt, liegt sie parallel zum unteren Widerstand und verändert das Verhältnis – der Teiler bricht ein.",x:"Faustregel: Der Querstrom durch den Teiler sollte mindestens zehnmal so groß sein wie der Strom in die Last. Sonst brauchst du einen Impedanzwandler."},
{c:"elek",t:"Die Zeitkonstante Tau",b:"R mal C ergibt eine Zeit. Nach einem Tau ist ein Kondensator auf 63 % geladen, nach fünf Tau praktisch voll. 10 kΩ und 100 nF ergeben 1 ms – damit lassen sich Filter, Verzögerungen und Entprellungen direkt auslegen.",x:"Umgekehrt gilt für Tiefpässe: Grenzfrequenz = 1 / (2π·R·C). Mit denselben Werten also rund 160 Hz."},
{c:"elek",t:"Masse ist nicht überall gleich",b:"Jede Leiterbahn hat Widerstand. Fließt ein hoher Strom durch die Masseleitung, entsteht darüber ein Spannungsabfall – und plötzlich liegt der Sensor auf einem anderen Nullpunkt als der Mikrocontroller. Das ist der Klassiker bei falschen Messwerten.",x:"Lösung: Sternpunkt-Masse oder eine durchgehende Massefläche. Leistungs- und Signalmasse erst an einem einzigen Punkt zusammenführen."},
{c:"elek",t:"Warum die Multimeter-Sicherung fliegt",b:"Im Spannungsbereich hat das Messgerät einige Megaohm Innenwiderstand. Im Strombereich sind es Milliohm – es ist quasi ein Stück Draht. Wer in dieser Stellung an eine Spannungsquelle geht, legt einen Kurzschluss an.",x:"Angewohnheit, die Geräte rettet: nach jeder Strommessung sofort zurück auf Volt drehen und die Prüfspitze umstecken."},
{c:"elek",t:"Tastkopf auf 10:1 stellen",b:"In Stellung 1:1 belastet der Tastkopf die Schaltung mit etwa 100 pF – genug, um schnelle Signale zu verformen oder einen Oszillator zum Stehen zu bringen. Auf 10:1 sinkt die Last auf rund 15 pF, dafür wird das Signal gezehntelt.",x:"Vor der Messung immer am Kalibrier-Ausgang abgleichen: das Rechteck muss scharfe Ecken haben, weder überschwingen noch verschliffen sein."},
{c:"elek",t:"PWM ist keine Analogspannung",b:"PWM schaltet zwischen voll an und voll aus und variiert nur das Verhältnis. Ein Motor oder eine LED mitteln das träge genug, um es als Helligkeit oder Drehzahl wahrzunehmen. Ein Messgerät sieht dagegen Rechtecke.",x:"Echte Analogspannung entsteht erst mit Tiefpass dahinter oder mit einem DAC. Und Vorsicht: viele Sensoren und Verstärker reagieren auf die Schaltflanken, nicht auf den Mittelwert."},
{c:"elek",t:"I2C ist ein Open-Drain-Bus",b:"Kein Teilnehmer darf die Leitung aktiv auf High ziehen – sie kann nur nach Masse gezogen oder losgelassen werden. High kommt ausschließlich über die Pull-ups. Deshalb funktioniert I2C ohne sie überhaupt nicht.",x:"Bei mehreren Modulen addieren sich oft mehrere Pull-ups parallel. Dann wird der Bus zu niederohmig und die Flanken zu steil – auf den Platinen die überzähligen entfernen."},
{c:"elek",t:"UART, SPI oder I2C",b:"UART ist asynchron, braucht keine Taktleitung, aber beide Seiten müssen dieselbe Baudrate raten. SPI hat einen Takt, ist sehr schnell, kostet aber eine Chip-Select-Leitung pro Gerät. I2C braucht nur zwei Leitungen für viele Geräte, ist dafür langsamer.",x:"Grobe Orientierung: Displays und Speicher über SPI, Sensoren über I2C, Module und Debug-Ausgaben über UART."},
{c:"elek",t:"Warum CAN 120 Ohm braucht",b:"CAN überträgt differenziell auf zwei verdrillten Leitungen. Bei den Flankensteilheiten verhält sich das Kabel wie eine Leitung mit Wellenwiderstand – ohne Abschluss an beiden Enden wird das Signal reflektiert und überlagert sich selbst.",x:"Zwei Widerstände à 120 Ω, jeweils am physikalischen Ende des Strangs, nicht in der Mitte. Misst man den Bus im Ruhezustand, sollten rund 60 Ω zwischen CAN-H und CAN-L stehen."},
{c:"elek",t:"Differenziell heißt störfest",b:"Auf CAN, RS485 und USB zählt nicht die Spannung gegen Masse, sondern die Differenz zwischen zwei Leitungen. Eine eingekoppelte Störung trifft beide gleich und fällt bei der Differenzbildung heraus.",x:"Das funktioniert nur, wenn die Leitungen verdrillt sind und denselben Weg nehmen. Ein aufgetrennter Draht im Kabelbaum macht aus dem Vorteil sofort eine Antenne."},
{c:"elek",t:"Baudratenfehler summieren sich",b:"UART tastet in der Mitte jedes Bits ab. Weicht der Takt um mehr als etwa 2 % ab, ist die Abtastung am Ende eines 10-Bit-Frames so weit verschoben, dass sie ins Nachbarbit rutscht – man bekommt sporadischen Zeichensalat.",x:"Deshalb haben viele Mikrocontroller Quarze mit krummen Werten wie 11,0592 MHz: daraus lassen sich Standard-Baudraten exakt teilen."},
{c:"elek",t:"Der ADC misst nur Verhältnisse",b:"Ein Analog-Digital-Wandler vergleicht die Eingangsspannung mit seiner Referenz. Ist die Referenz die Versorgungsspannung, wandert jeder Messwert mit, sobald die Versorgung einbricht – etwa wenn ein Motor anläuft.",x:"Für stabile Messungen eine eigene Referenz verwenden. Und: 12 Bit Auflösung bedeuten nicht 12 Bit Genauigkeit – Rauschen und Linearitätsfehler fressen oft die unteren zwei bis drei Bit."},
{c:"elek",t:"Taster prellen",b:"Ein mechanischer Kontakt schließt nicht einmal, sondern springt für 1–10 ms mehrfach. Ein Mikrocontroller ist schnell genug, jeden dieser Sprünge als eigenen Tastendruck zu zählen.",x:"Entprellen geht per Software (nach der ersten Flanke 20 ms lang nicht mehr hinschauen) oder per RC-Glied mit Schmitt-Trigger-Eingang. Software reicht fast immer."},
{c:"elek",t:"ESD tötet leise",b:"Ein Funke, den du spürst, hat mehrere tausend Volt. Ein CMOS-Gate stirbt schon bei Spannungen, die du nicht merkst. Oft geht das Bauteil nicht sofort kaputt, sondern bekommt einen Vorschaden und fällt Wochen später aus.",x:"Im trockenen Hallenwinter ist das Risiko am größten. Armband oder wenigstens vorher an blanken, geerdeten Metallteilen entladen – und Bauteile in der antistatischen Tüte lassen, bis sie verbaut werden."},
{c:"elek",t:"Bleifrei braucht mehr Hitze",b:"Bleihaltiges Lot schmilzt bei 183 °C, gängiges bleifreies SAC bei 217–227 °C. Es fließt zäher, benetzt schlechter und die fertige Lötstelle sieht matt aus – bei bleihaltigem Lot wäre das ein Fehlerzeichen, hier ist es normal.",x:"Für Reparaturen ist bleihaltiges Lot immer noch angenehmer. Beides in derselben Stelle zu mischen ergibt eine Legierung mit unklarem Schmelzpunkt – lieber vorher absaugen."},
{c:"elek",t:"Was Flussmittel wirklich tut",b:"Es klebt nicht und es senkt nicht den Schmelzpunkt. Es löst chemisch die Oxidschicht auf Kupfer und Zinn auf und hält bis zum Erstarren neuen Sauerstoff fern. Ohne diese saubere Metalloberfläche kann das Lot keine Verbindung eingehen.",x:"Deshalb funktioniert altes Lot ohne zusätzliches Flussmittel oft schlecht: die Seele ist verbraucht, bevor die Stelle heiß genug ist. Flussmittelstift für SMD-Arbeit ist die beste kleine Anschaffung."},
{c:"elek",t:"Kalte Lötstelle erkennen",b:"Eine gute Stelle ist konkav und läuft flach am Pad aus – das Lot hat benetzt. Eine kalte Stelle ist kugelig, grau und sitzt wie ein Tropfen auf dem Pad, ohne Übergang. Elektrisch kann sie zunächst leiten und später aussetzen.",x:"Ursache ist fast nie zu wenig Lot, sondern zu wenig Wärme am Pad. Spitze an Bauteil und Pad gleichzeitig, dann Lot zuführen – nicht Lot auf die Spitze und dann hin."},
{c:"elek",t:"Reflow ist ein Temperaturprofil",b:"Vier Phasen: langsames Vorheizen, Halten bei rund 150 °C zum Aktivieren des Flussmittels, kurzer Peak über den Schmelzpunkt, dann kontrolliertes Abkühlen. Zu schnelles Hochfahren lässt Bauteile durch Dampfdruck springen, zu langes Halten verbraucht das Flussmittel.",x:"Beim Abkühlen macht Geschwindigkeit die Kornstruktur fein und die Lötstelle mechanisch fest – aber zu schnell erzeugt Spannungen in Keramikbauteilen."},
{c:"elek",t:"Leiterbahnbreite und Strom",b:"Eine Außenlage mit 35 µm Kupfer trägt bei 1 mm Breite rund 3 A mit etwa 10 K Erwärmung. Innenlagen schaffen bei gleicher Breite nur die Hälfte, weil die Wärme schlechter weg kann.",x:"Nicht nur die Erwärmung beachten, sondern auch den Spannungsabfall. Bei Messsignalen ist der oft das eigentliche Problem, lange bevor etwas warm wird."},
{c:"elek",t:"Lange Leitungen sind Antennen",b:"Eine Leiterbahn strahlt umso besser, je näher ihre Länge an einem Viertel der Wellenlänge der enthaltenen Frequenzen liegt. Bei steilen Digitalflanken stecken Oberwellen bis in den dreistelligen Megahertzbereich – da reichen wenige Zentimeter.",x:"Die wirksamste Gegenmaßnahme ist nicht Abschirmung, sondern eine kurze Rückleitung: Signal und Masse direkt nebeneinander führen, damit die aufgespannte Fläche klein bleibt."},
{c:"elek",t:"Lithium lädt in zwei Phasen",b:"Zuerst konstanter Strom, bis die Zellspannung 4,2 V erreicht. Dann konstante Spannung, während der Strom von selbst abfällt. Ist er auf etwa 3 % gesunken, ist die Zelle voll. Eine Li-Zelle wird nie mit fester Spannung dauergeladen.",x:"Ladeschlussspannung auf 4,1 V zu begrenzen kostet rund 10 % Kapazität, kann die Zyklenzahl aber mehr als verdoppeln. Deshalb laden Autohersteller nie auf 100 %."},
{c:"elek",t:"Wofür ein BMS wirklich da ist",b:"Es schützt jede einzelne Zelle vor Über- und Tiefentladung und gleicht Spannungsunterschiede im Pack aus. In Reihe geschaltete Zellen driften mit der Zeit auseinander; ohne Balancing wird die schwächste Zelle jedes Mal überfahren.",x:"Ein Pack ist immer nur so gut wie seine schlechteste Zelle. Deshalb beim Selbstbau Zellen nach Kapazität und Innenwiderstand sortieren, nicht nur nach Typ."},
{c:"elek",t:"Step-Up frisst Eingangsstrom",b:"Leistung bleibt erhalten. Wer aus 3,7 V auf 12 V bei 1 A hochsetzt, zieht eingangsseitig über 3,5 A plus Verluste. Das übersehen viele bei Akkuprojekten – die Zelle wird zur Grenze, nicht der Wandler.",x:"Deshalb ist ein Step-Down fast immer der effizientere Weg: von einer höheren Quelle herunter statt von einer niedrigen herauf."},
{c:"elek",t:"Spannungsabfall im Kabel",b:"Bei 12 V sind 0,5 V Verlust schon 4 % – bei 230 V wäre derselbe Verlust bedeutungslos. Deshalb ist Querschnitt im Niedervolt-Bereich viel kritischer als in der Hausinstallation, obwohl die Spannung ungefährlich ist.",x:"Rechnung: 2 m Hin- und Rückleitung mit 1,5 mm² haben rund 24 mΩ. Bei 10 A fallen damit 0,24 V ab – bei 0,75 mm² schon fast das Doppelte."},
{c:"elek",t:"Der IP-Code hat zwei Ziffern",b:"Die erste steht für Fremdkörper- und Berührschutz (bis 6: staubdicht), die zweite für Wasser. IP65 ist Strahlwasser, IP67 zeitweiliges Untertauchen, IP68 dauerndes. Ein Gehäuse kann IP67 sein, ohne IP65 zu erfüllen – die Prüfungen sind verschieden.",x:"Praktisch relevant: IP-Schutz gilt nur mit korrekt montierter Dichtung und Kabelverschraubung. Die häufigste Undichtigkeit ist nicht das Gehäuse, sondern die Kabeleinführung."},
{c:"elek",t:"Die H-Brücke",b:"Vier Schalter in H-Form legen einen Motor wahlweise in beide Richtungen an die Versorgung. Wichtig ist die Totzeit: schalten obere und untere Seite gleichzeitig durch, entsteht ein Kurzschluss quer durch die Brücke.",x:"Deshalb haben Treiber-ICs eine eingebaute Verriegelung. Beim Selbstbau aus diskreten MOSFETs ist genau das der Fehler, der teure Rauchwolken erzeugt."},
{c:"elek",t:"Der Watchdog",b:"Ein Zähler läuft ständig herunter. Erreicht er null, wird der Mikrocontroller zurückgesetzt. Die Software muss ihn regelmäßig nachladen – hängt sie in einer Endlosschleife, tut sie das nicht mehr und das Gerät startet neu.",x:"Wichtig: den Watchdog nicht aus einem Interrupt heraus füttern. Der läuft oft noch, während die Hauptschleife längst steht – dann merkt niemand etwas."},
{c:"elek",t:"Warum 3,3 V und 5 V sich nicht vertragen",b:"Ein 5-V-Signal an einem 3,3-V-Pin lässt Strom durch die interne Schutzdiode in die Versorgung fließen. Kurzfristig funktioniert das oft, langfristig zerstört es den Pin oder hebt die ganze Versorgungsschiene an.",x:"Für Eingänge reicht ein Spannungsteiler. Für bidirektionale Busse wie I2C braucht es einen Pegelwandler mit MOSFETs – ein Widerstand allein genügt dort nicht."},
{c:"elek",t:"Messen statt raten",b:"Bei jeder Fehlersuche gilt die Reihenfolge: erst Versorgungsspannung direkt am Baustein, dann Masse, dann Takt, dann Signal. Über die Hälfte aller vermeintlich defekten Schaltungen scheitert an einer der ersten beiden Stufen.",x:"Und immer unter Last messen. Ein Netzteil, das im Leerlauf 5,0 V liefert und unter Last auf 3,8 V einbricht, sieht im Multimeter erst mal völlig gesund aus."},

/* ---------- AUTO & OLDTIMER ---------- */
{c:"auto",t:"Verdichtung und Klopfen",b:"Je höher verdichtet wird, desto besser der thermische Wirkungsgrad. Aber ab einem Punkt zündet das Gemisch durch Druck und Hitze von selbst, bevor die Kerze auslöst. Diese unkontrollierte Verbrennung schlägt gegen den aufsteigenden Kolben.",x:"Klopfen klingt harmlos, ist aber die zerstörerischste Betriebsart überhaupt: geschmolzene Kolbenränder entstehen in Sekunden, nicht in Tagen."},
{c:"auto",t:"Oktanzahl ist keine Leistung",b:"Die Oktanzahl gibt nur die Klopffestigkeit an, nicht den Energiegehalt. 102 Oktan enthalten nicht mehr Energie als 95. Leistung bringt hochoktaniger Sprit nur, wenn der Motor die Zündung wegen Klopfen zurücknehmen musste.",x:"Bei einem Oldtimer ohne Klopfsensor bringt teurer Sprit deshalb gar nichts – dort ist der Zündzeitpunkt mechanisch fest eingestellt."},
{c:"auto",t:"Warum vor OT gezündet wird",b:"Die Verbrennung braucht Zeit, ungefähr zwei Millisekunden. Der maximale Druck soll etwa 15° nach dem oberen Totpunkt anliegen, wenn der Kurbeltrieb den besten Hebel hat. Bei hoher Drehzahl bleibt weniger Zeit, also muss früher gezündet werden.",x:"Genau das macht die Fliehkraftverstellung im Verteiler. Sind ihre Federn müde oder die Gewichte fest, stimmt die Zündung nur noch im Leerlauf."},
{c:"auto",t:"Der Vergaser nutzt Unterdruck",b:"Im verengten Querschnitt des Venturi steigt die Luftgeschwindigkeit und der statische Druck fällt. Dieser Unterdruck saugt Kraftstoff aus der Düse – niemand pumpt aktiv ein, die Luft holt sich den Sprit selbst.",x:"Deshalb reagiert ein Vergaser auf Luftdruck und Temperatur. Im Winter oder in den Bergen verschiebt sich das Gemisch, obwohl an der Einstellung nichts geändert wurde."},
{c:"auto",t:"Warum der Choke fett macht",b:"Kalter Kraftstoff verdampft schlecht und schlägt sich an kalten Saugrohrwänden nieder. Damit trotzdem genug zündfähiges Gemisch am Zylinder ankommt, muss deutlich mehr eingespritzt werden als theoretisch nötig.",x:"Bleibt der Choke hängen, läuft der Motor warm zu fett: Ölverdünnung, verkokte Kerzen und stark erhöhter Verbrauch – oft die Ursache für angeblich defekte Zylinder."},
{c:"auto",t:"Sprungsonde und Breitbandsonde",b:"Eine Sprungsonde kennt im Grunde nur zwei Zustände: Ihre Spannung springt bei Lambda 1 von etwa 0,1 V auf 0,9 V. Damit kann die Regelung nur ständig um den Punkt herum pendeln. Eine Breitbandsonde misst den tatsächlichen Wert auch weit daneben.",x:"Deshalb schwankt die Spannung einer intakten Sprungsonde im Betrieb ständig. Ein konstanter Mittelwert ist ein Fehlerzeichen, kein gutes Signal."},
{c:"auto",t:"Common Rail: Druck ist die halbe Miete",b:"Mit 1600–2000 bar wird der Diesel so fein zerstäubt, dass er nahezu vollständig verbrennt. Sinkt der Raildruck oder ist eine Düse verschlissen, werden die Tropfen größer – der Motor läuft rau, nagelt und rußt.",x:"Ein Injektor, der bei 2000 bar nicht mehr dicht schließt, ist im Leerlauf am auffälligsten. Deshalb hört man den Defekt oft nur bei niedriger Drehzahl."},
{c:"auto",t:"Rücklaufmengen messen",b:"Jeder Injektor gibt Steuermengen in den Rücklauf zurück. Ist er innen verschlissen, steigt diese Menge stark an. Mit Messbechern an den Rückläufen im Leerlauf zeigt sich der schlechte Injektor sofort als Ausreißer.",x:"Die Absolutmenge ist je nach Motor unterschiedlich – entscheidend ist der Vergleich untereinander. Ein Zylinder mit doppelter Rücklaufmenge ist der Kandidat."},
{c:"auto",t:"Glühkerzen für die Kompression",b:"Ein Diesel zündet durch Kompressionswärme. Bei kaltem Motor geht so viel Wärme in die Wände, dass die Zündtemperatur nicht erreicht wird. Die Glühkerze erzeugt einen heißen Punkt im Brennraum, an dem die Verbrennung startet.",x:"Moderne Systeme glühen auch nach dem Start noch nach – für saubere Verbrennung und weniger Weißrauch in der Warmlaufphase."},
{c:"auto",t:"Das Wastegate begrenzt den Turbo",b:"Ein Abgasturbolader würde mit steigender Drehzahl immer mehr Druck erzeugen. Das Wastegate leitet einen Teil des Abgases am Turbinenrad vorbei und deckelt so den Ladedruck.",x:"Bleibt es offen hängen, fehlt Leistung ohne Fehlerspeichereintrag. Bleibt es zu, gibt es Überdruck – und dann schaltet die Steuerung in den Notlauf."},
{c:"auto",t:"Warum Ladeluft gekühlt wird",b:"Komprimierte Luft wird heiß und dehnt sich aus – heiße Luft enthält also weniger Sauerstoff pro Volumen. Der Ladeluftkühler macht aus demselben Ladedruck deutlich mehr Füllung und senkt gleichzeitig die Klopfneigung.",x:"Deshalb bringt ein größerer Ladeluftkühler oft mehr als mehr Ladedruck – und er kostet nichts an Haltbarkeit."},
{c:"auto",t:"Warum das AGR verkokt",b:"Abgasrückführung senkt die Verbrennungstemperatur und damit Stickoxide. Das rückgeführte Abgas enthält aber Ruß, der sich mit Ölnebel aus der Kurbelgehäuseentlüftung zu einer zähen Schicht im Ansaugtrakt verbindet.",x:"Kurzstrecke verschärft das, weil der Motor selten heiß genug wird. Eine verengte Ansaugbrücke erzeugt Leistungsverlust, der sich über Wochen einschleicht und deshalb kaum auffällt."},
{c:"auto",t:"Die DPF-Regeneration",b:"Der Rußpartikelfilter wird freigebrannt, indem spät nacheingespritzt wird und die Abgastemperatur auf über 600 °C steigt. Das dauert 10–20 Minuten und funktioniert nur bei ausreichender Fahrgeschwindigkeit.",x:"Wer währenddessen abstellt, sammelt unverbrannten Kraftstoff im Öl. Deshalb steigt bei DPF-Fahrzeugen mit Kurzstrecke der Ölstand statt zu sinken – und verdünntes Öl schmiert schlecht."},
{c:"auto",t:"Der Zweitakter braucht Gegendruck",b:"Beim Zweitakter sind Einlass und Auslass gleichzeitig offen. Ein Teil des frischen Gemischs würde direkt hinausströmen. Der Gegenkonus im Resonanzauspuff wirft eine Druckwelle zurück, die genau im richtigen Moment das entwichene Gemisch zurückschiebt.",x:"Deshalb bringt ein größerer Zylinder ohne angepassten Auspuff und Vergaserbedüsung fast nichts: Die Füllung entsteht nicht allein aus Hubraum, sondern aus der Abstimmung der gesamten Gassäule."},
{c:"auto",t:"Warum der Resonanzauspuff nur in einem Band wirkt",b:"Die Druckwelle läuft mit fester Schallgeschwindigkeit durch das Rohr. Ihre Laufzeit passt nur in einem schmalen Drehzahlbereich zum Steuerzeitenfenster. Darüber und darunter kommt sie zu früh oder zu spät.",x:"Ein langes Rohr schiebt die Wirkung nach unten, ein kurzes nach oben. Zweitakt-Tuning ist deshalb vor allem Gaswechsel-Abstimmung, nicht Hubraum."},
{c:"auto",t:"Ventilspiel ist Absicht",b:"Ventile dehnen sich im Betrieb aus. Ohne Spiel im kalten Zustand würden sie im heißen Motor nicht mehr schließen – dann fehlt Kompression und der Ventilteller verbrennt, weil er seine Wärme nur über den Sitz abgeben kann.",x:"Zu großes Spiel klappert nur und verkürzt die Öffnungszeit. Zu kleines Spiel ist der teure Fehler: es zerstört Ventil und Sitz."},
{c:"auto",t:"Zahnriemen oder Steuerkette",b:"Der Riemen läuft leiser, ist leichter und billiger, hat aber ein festes Wechselintervall. Die Kette ist theoretisch für die Motorlebensdauer ausgelegt, längt sich aber – und mit ihr verschieben sich die Steuerzeiten.",x:"Eine gelängte Kette meldet sich als Rasseln beim Kaltstart, bevor der Spanner Öldruck hat. Wer das ignoriert, riskiert denselben Schaden wie bei einem gerissenen Riemen."},
{c:"auto",t:"Das Differential und seine Schwäche",b:"In der Kurve legt das kurveninnere Rad einen kürzeren Weg zurück. Das Differential gleicht das aus, indem es Drehzahl verteilt – aber immer nur so viel Moment überträgt, wie das Rad mit der geringsten Traktion aufnehmen kann.",x:"Deshalb dreht auf Eis ein Rad frei und das andere steht still. Eine Sperre begrenzt diesen Ausgleich und schickt Moment wieder auf die Seite mit Grip."},
{c:"auto",t:"Feder und Dämpfer haben verschiedene Jobs",b:"Die Feder trägt das Gewicht und bestimmt, wie weit das Auto einfedert. Der Dämpfer trägt nichts – er wandelt nur die Bewegungsenergie in Wärme und verhindert, dass die Feder nachschwingt.",x:"Härtere Federn ohne passende Dämpfer machen das Auto nicht sportlicher, sondern unruhig: die Räder verlieren durch unkontrolliertes Nachfedern regelmäßig Bodenkontakt."},
{c:"auto",t:"Sturz, Spur und Nachlauf",b:"Sturz ist die Neigung des Rades zur Senkrechten, Spur die Stellung zueinander von oben gesehen, Nachlauf die Neigung der Lenkachse zur Seite. Nachlauf sorgt dafür, dass die Lenkung von selbst geradeaus zurückläuft.",x:"Falsche Spur frisst Reifen am schnellsten – einige Millimeter genügen für sichtbaren Verschleiß nach wenigen tausend Kilometern. Sturz verschleißt einseitig, aber langsamer."},
{c:"auto",t:"Bremsflüssigkeit zieht Wasser",b:"DOT-4 ist hygroskopisch und nimmt Feuchtigkeit aus der Luft auf – über Schläuche und den Ausgleichsbehälter. Der Siedepunkt sinkt von rund 230 °C auf unter 150 °C bei 3 % Wasseranteil.",x:"Das merkt man nicht im Alltag, sondern beim zweiten harten Bremsen bergab: Der Wasseranteil verdampft, das Gas lässt sich komprimieren und das Pedal geht durch."},
{c:"auto",t:"Fading hat zwei Ursachen",b:"Belagfading: Der Reibbelag wird so heiß, dass er ausgast und ein Gasfilm den Reibwert senkt. Flüssigkeitsfading: Die Bremsflüssigkeit kocht und es entstehen komprimierbare Dampfblasen. Ersteres gibt ein hartes Pedal ohne Wirkung, zweiteres ein weiches.",x:"Deshalb ist das Pedalgefühl bei nachlassender Bremse die entscheidende Diagnose-Information."},
{c:"auto",t:"Masseprobleme bei Oldtimern",b:"Im 12-V-Bordnetz läuft der Rückstrom über die Karosserie. Rost an einem Massepunkt erzeugt Widerstand, und der Strom sucht sich einen anderen Weg – oft durch Seilzüge, Tachowellen oder Bremsleitungen.",x:"Klassisches Symptom: Das Rücklicht flackert, wenn der Blinker läuft. Die Ursache ist fast nie die Lampe, sondern die Masseverbindung der Leuchteneinheit."},
{c:"auto",t:"Lichtmaschine oder Gleichstromdynamo",b:"Der Dynamo liefert erst ab höherer Drehzahl Strom und braucht einen mechanischen Regler mit Rückstromschalter. Die Drehstromlichtmaschine erzeugt schon im Leerlauf genug und regelt elektronisch.",x:"Beim Umrüsten wird oft die Polarität übersehen: Viele Fahrzeuge bis in die 60er hatten Pluspol an Masse. Eine moderne Lichtmaschine geht daran sofort kaputt."},
{c:"auto",t:"Die Zündspule ist ein Transformator",b:"Der Unterbrecherkontakt lässt Strom durch die Primärwicklung fließen und baut ein Magnetfeld auf. Beim Öffnen bricht es schlagartig zusammen und induziert in der vieltausendfach gewickelten Sekundärseite bis zu 20.000 V.",x:"Der Kondensator am Unterbrecher ist kein Zubehör: Ohne ihn zieht der öffnende Kontakt einen Lichtbogen, brennt ab und die Zündspannung bricht ein."},
{c:"auto",t:"Rost braucht drei Dinge",b:"Eisen, Sauerstoff und Elektrolyt – meist Wasser mit Salz. Fehlt eines, passiert nichts. Deshalb rostet ein Auto in der trockenen Halle kaum und in der feuchten Garage mit Salzresten am schnellsten.",x:"Gefährlicher als offener Rost ist der unter Lack und Unterbodenschutz: dort bleibt Feuchtigkeit stehen und Sauerstoffmangel erzeugt die besonders aggressive Lochkorrosion."},
{c:"auto",t:"Kriterien fürs H-Kennzeichen",b:"Das Fahrzeug muss mindestens 30 Jahre alt sein, weitgehend dem Originalzustand entsprechen und in gutem, erhaltenem Zustand sein. Beurteilt wird das per Gutachten nach §23 StVZO.",x:"Zeitgenössische Umbauten sind oft zulässig, wenn sie in den ersten zehn Jahren üblich waren. Moderne Technik im Innenraum ist der häufigste Ablehnungsgrund."},
{c:"auto",t:"Die DOT-Nummer auf dem Reifen",b:"Die letzten vier Ziffern der DOT-Kennung sind Woche und Jahr der Herstellung. 2319 heißt 23. Woche 2019. Gummi altert auch ohne Fahrbetrieb – die Weichmacher entweichen und das Material wird hart und rissig.",x:"Bei Oldtimern mit wenig Laufleistung ist das relevanter als das Profil: Reifen über zehn Jahre haben oft noch 6 mm Profil und trotzdem kaum noch Haftung."},
{c:"auto",t:"Drehmoment und Leistung",b:"Drehmoment ist die Kraft am Hebel, Leistung ist Drehmoment mal Drehzahl. Deshalb hat jeder Motor sein Drehmomentmaximum bei niedrigerer Drehzahl als sein Leistungsmaximum – rechnerisch zwangsläufig.",x:"Für das Fahrgefühl zählt das Drehmoment am Rad, also nach der Übersetzung. Deshalb kann ein hochdrehender kleiner Motor mit kurzer Übersetzung kräftiger wirken als ein großer."},
{c:"auto",t:"Kompressionstest und Druckverlusttest",b:"Der Kompressionstest sagt, ob ein Zylinder Druck aufbaut. Der Druckverlusttest sagt, wohin er entweicht: Zischen im Ansaugtrakt heißt Einlassventil, im Auspuff Auslassventil, im Öleinfüllstutzen Kolbenringe, Blasen im Kühler heißt Zylinderkopfdichtung.",x:"Deshalb ist der Druckverlusttest die eigentlich diagnostische Messung – der Kompressionstest zeigt nur, dass etwas nicht stimmt."},

/* ---------- FINANZEN ---------- */
{c:"fin",t:"Zinseszins ist eine Kurve",b:"Der Unterschied zwischen einfacher Verzinsung und Zinseszins ist in den ersten Jahren fast unsichtbar und wird danach dominant. Bei 7 % über 30 Jahre stammt mehr als die Hälfte des Endwerts aus den letzten zehn Jahren.",x:"Deshalb ist bei langfristigem Aufbau der Startzeitpunkt wichtiger als die Sparrate. Zehn Jahre früher anfangen schlägt eine doppelte Rate."},
{c:"fin",t:"Die 72er-Regel",b:"Teile 72 durch den Zinssatz in Prozent und du bekommst ungefähr die Jahre bis zur Verdopplung. Bei 6 % also 12 Jahre, bei 3 % 24 Jahre. Die Näherung ist zwischen 2 % und 15 % erstaunlich genau.",x:"Funktioniert auch rückwärts: bei 3 % Inflation halbiert sich die Kaufkraft in rund 24 Jahren. Das macht schleichende Entwertung greifbar."},
{c:"fin",t:"Nominal und real",b:"Nominal ist die Zahl auf dem Papier, real ist die Zahl nach Inflation. 4 % Zinsen bei 3 % Inflation sind real 1 %. Nur die reale Rendite sagt, ob deine Kaufkraft wächst.",x:"Deshalb kann ein Sparbuch mit positiven Zinsen trotzdem Geld vernichten. Und deshalb ist die Inflationsrate die wichtigste Zahl, die man nirgends aufgeschrieben bekommt."},
{c:"fin",t:"Gewinn ist nicht Liquidität",b:"Ein Auftrag kann profitabel sein und dich trotzdem in die Klemme bringen: Material bezahlst du sofort, die Rechnung wird nach 30 Tagen bezahlt. In der Zwischenzeit fehlt dir das Geld, nicht der Gewinn.",x:"Die meisten Betriebe gehen nicht an fehlender Rentabilität zugrunde, sondern an Zahlungsunfähigkeit. Deshalb ist die Liquiditätsvorschau wichtiger als die Gewinnrechnung."},
{c:"fin",t:"Deckungsbeitrag",b:"Verkaufspreis minus variable Kosten. Das ist der Betrag, der zur Deckung deiner Fixkosten übrig bleibt – nicht dein Gewinn. Erst wenn alle Deckungsbeiträge zusammen die Fixkosten übersteigen, verdienst du.",x:"Deshalb kann ein Auftrag mit kleinem Deckungsbeitrag trotzdem sinnvoll sein, solange die Maschine sonst stillstünde. Aber nur, solange er keinen besseren verdrängt."},
{c:"fin",t:"Der Break-even",b:"Fixkosten geteilt durch Deckungsbeitrag pro Stück ergibt die Stückzahl, ab der du in die Gewinnzone kommst. Ohne diese Zahl ist jede Preisdiskussion Bauchgefühl.",x:"Interessanter als der Punkt selbst ist die Steigung danach: Bei hohen Fixkosten und hohem Deckungsbeitrag wird es hinter dem Break-even schnell sehr profitabel – und davor sehr schmerzhaft."},
{c:"fin",t:"Der Maschinenstundensatz",b:"Abschreibung, Raum, Strom, Wartung, Verschleißteile und kalkulatorischer Zins, geteilt durch die realistisch produktiven Stunden im Jahr. Diese Zahl ist die Untergrenze, unter der eine Maschine Geld verliert.",x:"Der häufigste Fehler steckt im Nenner: Man rechnet mit theoretischen Betriebsstunden statt mit tatsächlich abrechenbaren. Realistisch sind oft 50–60 % der geplanten."},
{c:"fin",t:"Abschreibung ist ein Zeitproblem",b:"Du bezahlst eine Maschine heute, darfst sie steuerlich aber über Jahre verteilt als Aufwand ansetzen. Der Geldabfluss und die steuerliche Entlastung fallen also auseinander.",x:"Deshalb kann eine Investition den Gewinn kaum senken und trotzdem das Konto leeren. Wer nur auf die Gewinnrechnung schaut, unterschätzt genau diesen Effekt."},
{c:"fin",t:"Aufschlag ist nicht Marge",b:"30 % Aufschlag auf 100 € Einkauf ergibt 130 € Verkaufspreis – die Marge beträgt dann aber nur 23 %. Wer beide Begriffe verwechselt, kalkuliert systematisch zu knapp.",x:"Umrechnung: Marge = Aufschlag / (1 + Aufschlag). Für 30 % Marge brauchst du rund 43 % Aufschlag."},
{c:"fin",t:"Skonto ist teurer als es aussieht",b:"2 % Skonto bei Zahlung in 10 statt 30 Tagen bedeutet: du bekommst 2 % für 20 Tage Vorauszahlung. Aufs Jahr gerechnet sind das über 36 % Zinsen.",x:"Deshalb ist Skonto ziehen fast immer lohnend – und Skonto gewähren eine der teuersten Finanzierungsformen, die man Kunden anbieten kann."},
{c:"fin",t:"Opportunitätskosten",b:"Die wahren Kosten einer Entscheidung sind nicht das ausgegebene Geld, sondern die beste Alternative, die du dafür aufgibst. Vier Stunden an einem 80-€-Auftrag kosten dich den 300-€-Auftrag, den du in derselben Zeit hättest machen können.",x:"Deshalb ist die richtige Frage bei knapper Kapazität nie: Lohnt sich das? Sondern: Lohnt sich das mehr als das Beste, was ich sonst tun könnte?"},
{c:"fin",t:"Versunkene Kosten zählen nicht",b:"Bereits ausgegebenes Geld ist weg, egal wie du dich jetzt entscheidest. Es darf in die Entscheidung nicht einfließen. Trotzdem hält es Menschen zuverlässig in schlechten Projekten fest, weil sie schon so viel investiert haben.",x:"Der Test: Würde ich heute, ohne Vorgeschichte, neu in dieses Projekt einsteigen? Lautet die Antwort nein, ist das Vorher irrelevant."},
{c:"fin",t:"Streuung senkt Risiko, nicht Rendite",b:"Wenn die Teile eines Portfolios nicht gleichzeitig fallen, glättet sich der Verlauf, ohne dass die erwartete Rendite sinkt. Das ist einer der wenigen Effekte in der Finanzwelt, den man umsonst bekommt.",x:"Entscheidend ist die Korrelation. Zehn Aktien aus derselben Branche sind keine Streuung – sie fallen gemeinsam, wenn die Branche fällt."},
{c:"fin",t:"Volatilität ist nicht gleich Risiko",b:"Volatilität misst Schwankung – in beide Richtungen. Risiko ist die Möglichkeit, das Ziel zu verfehlen. Bei einem Anlagehorizont von 20 Jahren ist Schwankung kaum relevant; bei einem Zahlungstermin in sechs Monaten schon.",x:"Deshalb ist die Frage nie, ob etwas schwankt, sondern wann du das Geld brauchst. Der Horizont entscheidet, welche Schwankung wehtut."},
{c:"fin",t:"Wie ein Indexfonds funktioniert",b:"Statt Titel auszuwählen, bildet er einen Index einfach nach. Es gibt kein Team, das Entscheidungen trifft – deshalb sind die Kosten niedrig. Er ist per Konstruktion immer so gut wie der Markt, minus Gebühren.",x:"Der zweite Effekt ist wichtig: Weil kaum umgeschichtet wird, entstehen kaum Transaktionskosten und in vielen Ländern weniger laufende Steuerereignisse."},
{c:"fin",t:"Was 1 % Gebühr kostet",b:"Bei 7 % Bruttorendite über 30 Jahre frisst eine Kostenquote von 1 % statt 0,2 % rund ein Fünftel des Endvermögens. Der Unterschied wirkt jedes Jahr auf das gesamte Kapital, nicht nur auf den Ertrag.",x:"Deshalb ist die Kostenquote die einzige Kennzahl eines Anlageprodukts, die du sicher im Voraus kennst. Die Rendite ist eine Hoffnung, die Gebühr ist ein Fakt."},
{c:"fin",t:"Spread und Slippage",b:"Der Spread ist die Spanne zwischen Kauf- und Verkaufskurs – du verlierst ihn in dem Moment, in dem du kaufst. Slippage ist die zusätzliche Abweichung, weil dein Auftrag den Kurs bewegt oder sich der Markt in der Zwischenzeit verschiebt.",x:"Für Strategien mit vielen Trades sind diese beiden Posten oft größer als der theoretische Gewinn. Deshalb scheitern viele Systeme erst in der Praxis."},
{c:"fin",t:"Market oder Limit",b:"Eine Market-Order wird sofort ausgeführt, aber zu dem Preis, der gerade da ist. Eine Limit-Order legt den Preis fest, wird dafür aber vielleicht nie ausgeführt. Du wählst zwischen Ausführungssicherheit und Preissicherheit.",x:"In dünnen Märkten oder außerhalb der Haupthandelszeiten kann eine Market-Order deutlich schlechter ausgeführt werden, als die angezeigte Kursstellung vermuten lässt."},
{c:"fin",t:"Was Liquidität bedeutet",b:"Liquidität ist die Fähigkeit, eine Position zu schließen, ohne den Preis stark zu bewegen. In einem dünnen Orderbuch kann schon eine mittlere Order mehrere Prozent kosten – das steht in keinem Chart.",x:"Deshalb funktionieren Strategien im Backtest auf Papier und scheitern real: Historische Kurse zeigen, dass ein Preis existierte, nicht dass dort Volumen für dich war."},
{c:"fin",t:"Wie ein Margin Call entsteht",b:"Mit Hebel handelst du mit geliehenem Kapital. Fällt die Position, sinkt dein Eigenanteil überproportional. Unterschreitet er eine Schwelle, wird zwangsliquidiert – unabhängig davon, ob deine These später richtig gewesen wäre.",x:"Bei Hebel 10 genügen 10 % Kursbewegung gegen dich für den Totalverlust. Der Hebel vervielfacht nicht nur den Gewinn, sondern vor allem die Geschwindigkeit des Ausscheidens."},
{c:"fin",t:"Overfitting im Backtest",b:"Wer lange genug an Parametern dreht, findet immer eine Kombination, die in der Vergangenheit hervorragend funktioniert hätte. Das Modell hat dann Rauschen gelernt, nicht Struktur – und im Echtbetrieb bricht die Kurve zusammen.",x:"Gegenmittel: einen Teil der Daten von Anfang an wegsperren und erst ganz am Ende einmal darauf testen. Wer diesen Datensatz mehrfach benutzt, hat ihn ebenfalls verbraucht."},
{c:"fin",t:"Survivorship Bias",b:"Wer heute die Wertentwicklung aller existierenden Fonds oder Aktien auswertet, betrachtet nur die Überlebenden. Alles, was pleiteging oder geschlossen wurde, fehlt – die Bilanz sieht dadurch systematisch zu gut aus.",x:"Derselbe Denkfehler steckt in jeder Erfolgsgeschichte: Die gleiche Strategie bei denen, die gescheitert sind, sieht niemand mehr."},
{c:"fin",t:"Dividende ist kein Geschenk",b:"Am Ausschüttungstag fällt der Kurs rechnerisch um den Dividendenbetrag. Das Geld wandert aus dem Unternehmen auf dein Konto – dein Gesamtvermögen ändert sich dadurch zunächst nicht.",x:"Was sich ändert: Der Zeitpunkt der Besteuerung und die Tatsache, dass du Liquidität bekommst, ohne verkaufen zu müssen. Das ist ein Timing-Vorteil, keine Zusatzrendite."},
{c:"fin",t:"Wofür eine Reserve da ist",b:"Eine Liquiditätsreserve bringt keine Rendite. Ihr Zweck ist, dass du bei einem Ausfall nicht zum schlechtesten Zeitpunkt verkaufen oder teuer finanzieren musst. Sie verhindert Verluste, statt Gewinne zu erzeugen.",x:"Für Selbstständige mit schwankenden Eingängen gilt eine deutlich größere Reserve als für Angestellte – meist rechnet man in Monaten Fixkosten, nicht in Monatsgehältern."},
{c:"fin",t:"Nominalzins und Effektivzins",b:"Der Nominalzins ist der reine Zinssatz. Der Effektivzins enthält zusätzlich Gebühren, Auszahlungsverluste und den Zahlungsrhythmus. Nur er erlaubt es, zwei Angebote zu vergleichen.",x:"Achte auf die Tilgungsverrechnung: Wird jährlich statt monatlich verrechnet, zahlst du Zinsen auf bereits getilgtes Geld – im Effektivzins taucht das auf, im Nominalzins nicht."},
{c:"fin",t:"Anleihekurse laufen gegen den Zins",b:"Eine alte Anleihe mit 1 % Kupon wird unattraktiv, sobald neue mit 4 % ausgegeben werden. Damit sie trotzdem jemand kauft, muss ihr Kurs fallen, bis die Rendite bis Fälligkeit wieder marktgerecht ist.",x:"Je länger die Restlaufzeit, desto stärker dieser Effekt. Deshalb verlieren langlaufende Anleihen in Zinserhöhungsphasen deutlich mehr als kurzlaufende."},
{c:"fin",t:"Grenzsteuersatz",b:"Der Grenzsteuersatz gilt nur für den nächsten verdienten Euro, nicht für dein gesamtes Einkommen. Der Durchschnittssteuersatz liegt immer deutlich darunter. Mehr zu verdienen kann deshalb nie dazu führen, dass netto weniger bleibt.",x:"Relevant wird der Grenzsteuersatz genau dann, wenn du einen Zusatzauftrag bewertest oder eine Ausgabe vorziehen willst – dort ist er die richtige Rechengröße."},
{c:"fin",t:"Die Kleinunternehmerregelung",b:"Nach §19 UStG weist du keine Umsatzsteuer aus und musst keine abführen. Im Gegenzug kannst du keine Vorsteuer aus Einkäufen zurückholen. Die Regelung ist an Umsatzgrenzen gebunden, die regelmäßig angepasst werden.",x:"Für Privatkunden ist das ein Preisvorteil, für Geschäftskunden irrelevant – die holen sich die Umsatzsteuer ohnehin zurück. Der Kundenmix entscheidet, ob die Regelung günstig ist."},
{c:"fin",t:"Warum Investitionen ohne Vorsteuerabzug teurer sind",b:"Wer Umsatzsteuer abführt, kauft Maschinen effektiv zum Nettopreis. Ohne Vorsteuerabzug ist der Bruttopreis dein tatsächlicher Anschaffungspreis – bei größeren Anschaffungen ein spürbarer Unterschied.",x:"Deshalb wird die Frage nach der Regelbesteuerung meist nicht durch den Umsatz entschieden, sondern durch geplante Investitionen und den Anteil an Geschäftskunden. Das ist ein Fall für den Steuerberater, nicht fürs Bauchgefühl."},
{c:"fin",t:"Wachstum kostet Geld",b:"Mehr Aufträge heißen mehr Material, mehr Vorfinanzierung und längere Außenstände – alles vor der Bezahlung. Ein schnell wachsender Betrieb braucht deshalb mehr Liquidität als ein stagnierender, obwohl er profitabler ist.",x:"Das ist der Grund, warum Unternehmen an zu vielen Aufträgen scheitern können. Wachstum ohne Finanzierungsplan ist einer der häufigsten Insolvenzgründe."}

];
